def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change_ratio = (new - old) / old * 100
    return {
        "value": change_ratio,
        "trace": {
            "old_liability": old,
            "new_liability": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
